<template>
  <div class="app-container">
    <el-alert title="此页维护实际生效的查券与用户提示配置，提交走 /system/config。平台选项由公共 CPS 字典提供。" type="info" :closable="false" />
    <el-table v-loading="loading" :data="rows" style="margin-top:14px"><el-table-column label="配置项" prop="configName" min-width="180"/><el-table-column label="配置键" prop="configKey" min-width="260"/><el-table-column label="当前配置" min-width="260" show-overflow-tooltip><template slot-scope="s">{{s.row.configValue}}</template></el-table-column><el-table-column label="操作" width="90"><template slot-scope="s"><el-button type="text" size="mini" @click="edit(s.row)" v-hasPermi="['system:config:edit']">编辑</el-button></template></el-table-column></el-table>
    <el-dialog title="编辑查券配置" :visible.sync="open" width="640px" append-to-body><el-form :model="form" label-width="160px"><el-form-item label="配置项"><el-input v-model="form.configName" disabled/></el-form-item><el-form-item label="配置键"><el-input v-model="form.configKey" disabled/></el-form-item><el-form-item label="配置值"><el-input v-model="form.configValue" :type="longText(form.configKey)?'textarea':'text'" :rows="4"/></el-form-item><el-form-item label="备注"><el-input v-model="form.remark" type="textarea" :rows="2"/></el-form-item><el-form-item v-if="form.configKey==='cps.coupon.jd-union-id'" label="京东联盟账号"><el-tag v-if="platforms.length">可选平台：{{platformLabels}}</el-tag><span style="margin-left:8px">账号编号为普通配置，不是密钥</span></el-form-item></el-form><div slot="footer"><el-button type="primary" :loading="saving" @click="save">保存</el-button><el-button @click="open=false">取消</el-button></div></el-dialog>
  </div>
</template>
<script>
import { getCpsConfigList, getCpsConfig, saveCpsConfig, cpsDict } from '@/api/cps/settings'
const KEYS=['cps.coupon.cache-seconds','cps.coupon.minimum-commission','cps.coupon.message.no-commission','cps.coupon.show-no-commission','cps.coupon.message.low-commission','cps.coupon.message.pdd-comparison','cps.coupon.show-pdd-comparison','cps.coupon.binding-notice-minutes','cps.coupon.message.redpacket','cps.coupon.message.old-cart','cps.coupon.message.refund','cps.coupon.jd-union-id']
export default {name:'CpsCouponSettings',data(){return{loading:false,saving:false,rows:[],open:false,form:{},platforms:[]}},computed:{platformLabels(){return this.platforms.map(x=>x.label).join('、')}},created(){cpsDict().then(r=>{this.platforms=(r.data&&r.data.platforms)||[]});this.load()},methods:{load(){this.loading=true;getCpsConfigList({pageNum:1,pageSize:200}).then(r=>{this.rows=(r.rows||[]).filter(x=>KEYS.includes(x.configKey))}).finally(()=>{this.loading=false})},edit(row){getCpsConfig(row.configId).then(r=>{this.form={...r.data};this.open=true})},longText(k){return k.indexOf('message.')>=0},save(){if(this.form.configValue==null){this.$modal.msgError('请填写配置值');return}this.saving=true;saveCpsConfig(this.form).then(()=>{this.$modal.msgSuccess('查券配置保存成功');this.open=false;this.load()}).finally(()=>{this.saving=false})}}}
</script>
